import { headers } from 'next/headers'

export default async function Dashboard() {
  const requestHeaders = await headers()

  try {
    const host = requestHeaders.get('x-forwarded-host') ?? requestHeaders.get('host')
    const protocol = requestHeaders.get('x-forwarded-proto') ?? 'http'

    if (!host) {
      throw new Error('Missing request host')
    }

    const origin = `${protocol}://${host}`
    const fetchData = async (path: string) => {
      const response = await fetch(new URL(path, origin), { cache: 'no-store' })

      if (!response.ok) {
        throw new Error(`Failed to fetch ${path}: ${response.status}`)
      }

      return response.json()
    }

    const [analytics, notifications, settings] = await Promise.all([
      fetchData('/api/analytics'),
      fetchData('/api/notifications'),
      fetchData('/api/settings'),
    ])

    return (
      <div>
        <h2>Dashboard Content</h2>
        <section>
          <h3>Analytics</h3>
          <pre>{JSON.stringify(analytics, null, 2)}</pre>
        </section>
        <section>
          <h3>Notifications</h3>
          <pre>{JSON.stringify(notifications, null, 2)}</pre>
        </section>
        <section>
          <h3>Settings</h3>
          <pre>{JSON.stringify(settings, null, 2)}</pre>
        </section>
      </div>
    )
  } catch {
    return (
      <div>
        <h2>Dashboard Content</h2>
        <p role="alert">Unable to load dashboard data. Please try again later.</p>
      </div>
    )
  }
}

